import{_ as a,o as n,c as i,ai as l}from"./chunks/framework.Ba-VnP44.js";const b=JSON.parse('{"title":"Hooks / Scripts · 自动化执行","description":"","frontmatter":{},"headers":[],"relativePath":"ai/productivity/dev-spec/01-foundation/hooks-scripts.md","filePath":"ai/productivity/dev-spec/01-foundation/hooks-scripts.md"}'),e={name:"ai/productivity/dev-spec/01-foundation/hooks-scripts.md"};function p(r,s,t,o,c,h){return n(),i("div",null,[...s[0]||(s[0]=[l(`<h1 id="hooks-scripts-·-自动化执行" tabindex="-1">Hooks / Scripts · 自动化执行 <a class="header-anchor" href="#hooks-scripts-·-自动化执行" aria-label="Permalink to “Hooks / Scripts · 自动化执行”">​</a></h1><blockquote><p>第一层 · 能力底座。解决「哪些检查不该靠提示词提醒」——凡是&quot;漏了就出事、且能脚本判定&quot;的事情，交给脚本和 Hooks 自动执行，不依赖 AI 记得。</p></blockquote><h2 id="解决什么问题" tabindex="-1">解决什么问题 <a class="header-anchor" href="#解决什么问题" aria-label="Permalink to “解决什么问题”">​</a></h2><ul><li>靠提示词提醒「记得跑测试」，AI 偶尔就忘了。</li><li>同样的问题反复靠人肉检查，浪费时间。</li><li>密钥、禁改区这类红线，只在口头说过，没有自动拦截。</li><li>Hooks 装了一堆，误报太多，最后全被忽略。</li></ul><h2 id="核心内容" tabindex="-1">核心内容 <a class="header-anchor" href="#核心内容" aria-label="Permalink to “核心内容”">​</a></h2><h3 id="什么交给脚本" tabindex="-1">什么交给脚本 <a class="header-anchor" href="#什么交给脚本" aria-label="Permalink to “什么交给脚本”">​</a></h3><p>满足两个条件就该脚本化：</p><ol><li><strong>漏了就出事</strong>：不检查可能导致错误交付（构建失败、测试没过、密钥泄露）。</li><li><strong>能明确判定</strong>：结果是非黑即白，不需要业务判断。</li></ol><p>典型场景：</p><ul><li>构建、类型检查、单测。</li><li>密钥 / 敏感信息扫描。</li><li>禁改区 diff 检查。</li><li>遗留文件清理（临时文件、调试代码）。</li><li>提交前格式与 lint。</li></ul><p><strong>需要业务判断的不交给脚本</strong>：业务规则对不对、架构是否合理、需求理解是否准确——这些留给审查和人判定。</p><h3 id="hooks-与-scripts-的分工" tabindex="-1">Hooks 与 Scripts 的分工 <a class="header-anchor" href="#hooks-与-scripts-的分工" aria-label="Permalink to “Hooks 与 Scripts 的分工”">​</a></h3><table tabindex="0"><thead><tr><th>方式</th><th>适合做什么</th><th>特点</th></tr></thead><tbody><tr><td>Scripts</td><td>独立的检查、清理、验证</td><td>显式调用，可单独跑，好调试</td></tr><tr><td>Hooks</td><td>在特定时机自动触发（如提交前）</td><td>强制生效，但误报会打扰</td></tr></tbody></table><p>建议：先把检查写成能独立运行的脚本，确认稳定后，再把最关键的那几个挂到 Hook 上。<strong>不要一上来就挂一堆 Hook</strong>。</p><h3 id="设计原则" tabindex="-1">设计原则 <a class="header-anchor" href="#设计原则" aria-label="Permalink to “设计原则”">​</a></h3><ul><li><strong>快</strong>：检查要能快速给结果，慢检查单独跑，不阻塞日常操作。</li><li><strong>准</strong>：只报确定的问题，宁可少报不要误报，否则会被忽略。</li><li><strong>可解释</strong>：报错要说清「哪里不对、怎么改」，不只是「失败」。</li><li><strong>能跳过有记录</strong>：确需跳过时留痕并说明原因，不是静默忽略。</li></ul><h3 id="工具适配边界" tabindex="-1">工具适配边界 <a class="header-anchor" href="#工具适配边界" aria-label="Permalink to “工具适配边界”">​</a></h3><p>Hooks 的具体配置语法和触发时机因工具而异，以所用工具当前版本官方文档为准。本页只约定「什么该自动化、怎么设计检查」，不绑定某个工具的写法。</p><h2 id="检查脚本清单模板" tabindex="-1">检查脚本清单模板 <a class="header-anchor" href="#检查脚本清单模板" aria-label="Permalink to “检查脚本清单模板”">​</a></h2><div class="language-markdown line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># &lt;项目名&gt; 自动化检查清单</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| 检查项 | 脚本/命令 | 触发时机 | 失败处理 | 能否跳过 |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| ------ | --------- | -------- | -------- | -------- |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| 构建   | &lt;命令&gt;    | 提交前   | 必须修复 | 否 |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| 单测   | &lt;命令&gt;    | 提交前   | 必须修复 | 否 |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| 密钥扫描 | &lt;命令&gt;  | 提交前   | 立即处理 | 否 |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| 禁改区 diff | &lt;命令&gt; | 提交前 | 人工确认 | 需记录 |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| 格式/lint | &lt;命令&gt; | 提交前 | 建议修复 | 是 |</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 说明</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 哪些检查挂在 Hook 上：&lt;列表&gt;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 跳过规则：&lt;如何留痕&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><h2 id="可复制提示词" tabindex="-1">可复制提示词 <a class="header-anchor" href="#可复制提示词" aria-label="Permalink to “可复制提示词”">​</a></h2><details><summary><strong>把重复检查固化为脚本</strong></summary><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>下面这些检查我们每次都要手动做，请帮我设计成可复用的脚本方案。本轮只输出方案，不写代码。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>检查清单：</span></span>
<span class="line"><span>&lt;粘贴每次都做的检查&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>对每项请判断：</span></span>
<span class="line"><span>1. 是否「漏了就出事」且「能明确判定」——是则适合脚本化，否则说明留给人工审查。</span></span>
<span class="line"><span>2. 给出脚本要做的事、输入输出、失败时的报错信息（要说清怎么改）。</span></span>
<span class="line"><span>3. 建议触发时机：显式运行 / 提交前 Hook。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>约束：</span></span>
<span class="line"><span>- 只把最关键、最稳定的检查挂到 Hook，避免误报打扰。</span></span>
<span class="line"><span>- 慢检查单独跑，不阻塞日常操作。</span></span>
<span class="line"><span>- 需要跳过的检查给出留痕方式。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>输出：适合脚本化的清单 + 每项方案 + 建议挂 Hook 的最小集合。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br></div></div></details><details><summary><strong>审查现有 Hook 是否过载</strong></summary><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>请审查当前项目的 Hook/自动化检查配置，判断是否过载，只输出分析，不修改配置。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;粘贴现有 Hook/检查清单&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>检查项：</span></span>
<span class="line"><span>1. 哪些检查误报率高、实际很少拦住真问题。</span></span>
<span class="line"><span>2. 哪些检查太慢，拖慢日常操作。</span></span>
<span class="line"><span>3. 哪些检查需要业务判断，不该自动化。</span></span>
<span class="line"><span>4. 是否有「漏了就出事且能脚本判定」但没被覆盖的检查。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>输出：建议移除的、建议改为显式运行的、建议新增的，各给理由。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div></details><h2 id="验收要点" tabindex="-1">验收要点 <a class="header-anchor" href="#验收要点" aria-label="Permalink to “验收要点”">​</a></h2><ul><li>[ ] 脚本化的检查都满足「漏了就出事 + 能明确判定」。</li><li>[ ] 需要业务判断的检查留在人工审查，没有强行脚本化。</li><li>[ ] 检查快、准，报错可解释。</li><li>[ ] Hook 只挂最关键最稳定的几个，没有误报轰炸。</li><li>[ ] 跳过检查有留痕方式。</li></ul><p>能自动化的不要靠记忆，需要判断的不要硬自动化。分清楚这两类是关键。</p>`,26)])])}const k=a(e,[["render",p]]);export{b as __pageData,k as default};
